"use client";

import {
  Chart as ChartJS,
  LineElement,
  PointElement,
  LinearScale,
  CategoryScale,
  Tooltip,
  Legend,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(
  LineElement,
  PointElement,
  LinearScale,
  CategoryScale,
  Tooltip,
  Legend
);

interface PriceChartProps {
  history: {
    date: string;
    close: number;
  }[];
}

export default function PriceChart({ history }: PriceChartProps) {
  if (!history || history.length === 0) {
    return (
      <div className="p-4 rounded-lg bg-gray-900 text-gray-400 border border-gray-700">
        No chart data available.
      </div>
    );
  }

  const labels = history.map((h) => h.date);
  const prices = history.map((h) => h.close);

  const data = {
    labels,
    datasets: [
      {
        label: "Price",
        data: prices,
        borderColor: "#3b82f6",
        backgroundColor: "rgba(59, 130, 246, 0.3)",
        tension: 0.3,
        pointRadius: 0,
      },
    ],
  };

  const options = {
    responsive: true,
    plugins: {
      legend: { display: false },
    },
    scales: {
      x: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
      y: {
        ticks: { color: "#9ca3af" },
        grid: { color: "rgba(255,255,255,0.05)" },
      },
    },
  };

  return (
    <div className="bg-gray-900 p-4 rounded-lg border border-gray-700">
      <Line data={data} options={options} />
    </div>
  );
}
