"use client";

import { useState, useEffect } from "react";
import PriceChart from "../PriceChart";

export default function Dashboard() {
  const [symbol, setSymbol] = useState("AAPL");
  const [chartData, setChartData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);

  const fetchData = async () => {
    setLoading(true);
    setError(null);
    try {
      const response = await fetch(
        `${process.env.NEXT_PUBLIC_API_URL}/api/chart/hybrid?symbol=${symbol}`
      );
      if (!response.ok) {
        throw new Error(`HTTP error! status: ${response.status}`);
      }
      const data = await response.json();
      setChartData(data);
    } catch (err) {
      setError(err.message);
      console.error("Fetch error:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchData();
  }, [symbol]);

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-2xl font-bold mb-4">Stock Dashboard</h1>
      
      <div className="mb-4 flex gap-2">
        <input
          type="text"
          value={symbol}
          onChange={(e) => setSymbol(e.target.value.toUpperCase())}
          className="px-3 py-2 border rounded bg-gray-800 text-white border-gray-600"
          placeholder="Enter symbol (e.g., AAPL)"
        />
        <button
          onClick={fetchData}
          className="px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
        >
          Analyze
        </button>
      </div>

      {loading && <p className="text-gray-400">Loading...</p>}
      
      {error && (
        <div className="p-4 bg-red-900/50 text-red-400 rounded border border-red-700">
          Error: {error}
        </div>
      )}

      {chartData && (
        <div>
          <div className="mb-2">
            <span className="text-lg font-semibold">{chartData.symbol}</span>
            <span className="ml-4 text-green-400">
              ${chartData.latest_price?.toFixed(2)}
            </span>
          </div>
          <PriceChart history={chartData.data || []} />
          
          {chartData.summary && (
            <div className="mt-4 p-4 bg-gray-800 rounded border border-gray-700">
              <p className="text-gray-300">{chartData.summary}</p>
              <p className="text-xs text-gray-500 mt-2">
                Provider: {chartData.provider}
              </p>
            </div>
          )}
        </div>
      )}
    </div>
  );
}
